{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Ginsenoside Re is explicitly reported to be detected in brain after oral administration, indicating that it crosses the BBB, although brain concentrations are 8–15 times lower than plasma; this is direct evidence for meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The very close analogue Rg1 showed poor brain distribution (14.59 ng/mL) in a rat cerebral ischemic model, indicating that highly glycosylated ginsenosides can have limited brain uptake; this tempers the expected extent of CNS exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "The related ginsenoside Rg3 was detected in mouse brain by HPLC after systemic exposure, supporting that ginsenosides can achieve measurable brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ginsenoside Rh3 accumulated to 520 ng/g in rat hippocampus after oral administration, demonstrating meaningful brain exposure for a ginsenoside and supporting the transferability of CNS access to the query class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: ginsenoside Re has direct evidence of brain detection after oral administration (C10), supported by multiple related ginsenosides/saponins showing BBB permeability. The poor Rg1 brain concentration in an ischemic model is a caution but does not negate detectable CNS access.",
  "evidence_gaps": [
    "No quantitative unbound brain-to-plasma ratio or CSF data for Re itself.",
    "C04 is Rg1 in a cerebral ischemic model, not Re, and may not fully reflect normal BBB behavior.",
    "C10 reports qualitative detection without detailed brain concentration values for Re."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

